#include <bits/stdc++.h>
using namespace std;
int main(){int t; cin>>t;
 vector<tuple<char,char,double,long long,double>> legs(t);
 for(int i=0;i<t;i++){ string ty, sd; double k; long long q; double pr;
 cin>>ty>>sd>>k>>q>>pr;
 legs[i]={ty[0], sd[0], k, q, pr}; }
 int Q; cin>>Q; cout<<fixed<<setprecision(2);
 while(Q--){ double S; cin>>S; double total=0;
 for(auto&L:legs){ auto[ty,sd,k,q,pr]=L;
 double intr = (ty=='C') ? max(0.0, S-k) : max(0.0, k-S);
 double sign = (sd=='B') ? 1.0 : -1.0;
 total += sign*(intr-pr)*(double)q; }
 printf("%.2f\n", total); }
 return 0;}
